/**
 * pages/library/chains.html.ts - Outputs dist/pages/library/chains.html
 *
 * My Chains library page.
 * This is a Jinja2 template for the SSR page.
 */

import type { APIRoute } from 'astro';

// Import CSS so Tailwind scans this file's classes
import '../../../styles/global.css';

export const GET: APIRoute = () => {
  const template = `{% extends "layouts/base.html" %}

{% block title %}My Chains - Guitar Tone Shootout{% endblock %}
{% block description %}View and manage your signal chains.{% endblock %}

{% block content %}
<div
  data-testid="chains-library"
  class="container mx-auto px-4 py-8"
>
  <!-- Header -->
  <div class="mb-8">
    <div class="flex items-center justify-between">
      <div>
        <h1 class="text-2xl font-bold text-[var(--color-text-primary)] mb-2">
          My Chains
        </h1>
        <p class="text-[var(--color-text-secondary)]">
          Build and manage your signal chains for shootouts
        </p>
      </div>
      <a
        href="/library/chains/build"
        class="inline-flex items-center gap-2 px-4 py-2 bg-[var(--color-accent-primary)] hover:bg-[var(--color-accent-primary-hover)] text-white font-medium rounded-lg transition-colors"
        data-testid="build-chain-btn"
      >
        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor" class="w-5 h-5">
          <path d="M10.75 4.75a.75.75 0 00-1.5 0v4.5h-4.5a.75.75 0 000 1.5h4.5v4.5a.75.75 0 001.5 0v-4.5h4.5a.75.75 0 000-1.5h-4.5v-4.5z" />
        </svg>
        Build Chain
      </a>
    </div>
  </div>

  <!-- Chains list rendered server-side -->
  {% include "fragments/library/chains.html" %}
</div>
{% endblock %}

`;

  return new Response(template, {
    headers: {
      'Content-Type': 'text/html; charset=utf-8',
    },
  });
};
